package main

import (
 "context"
 "encoding/json"
 "net/http"
 "strconv"
 "strings"
 "time"
 "go.mau.fi/whatsmeow/types"
)
func userFeaturesJSON(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_=json.NewEncoder(w).Encode(v)}
func userDBID(r *http.Request)(string,bool){uid,ok:=portalUser(r);if !ok{return "",false};var id string;if err:=userDB.QueryRow(`SELECT id::text FROM public.app_users WHERE user_id=$1 AND status='active'`,uid).Scan(&id);err!=nil{return "",false};return id,true}
func userTasksHandler(w http.ResponseWriter,r *http.Request){id,ok:=userDBID(r);if !ok{userFeaturesJSON(w,401,map[string]any{"status":"error","message":"Login required"});return};rows,err:=userDB.Query(`SELECT t.id,t.title,t.message,t.target_phone,t.reward FROM public.task_definitions t WHERE t.active=true AND NOT EXISTS(SELECT 1 FROM public.task_claims c WHERE c.task_id=t.id AND c.user_id=$1::uuid AND c.status IN ('claimed','sending','sent')) ORDER BY t.created_at DESC`,id);if err!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error","message":"Could not load tasks"});return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var tid,title,msg,target string;var reward float64;if rows.Scan(&tid,&title,&msg,&target,&reward)==nil{out=append(out,map[string]any{"id":tid,"title":title,"message":msg,"target_phone":target,"reward":reward})}};userFeaturesJSON(w,200,map[string]any{"status":"success","tasks":out})}
func userWhatsAppHandler(w http.ResponseWriter,r *http.Request){id,ok:=userDBID(r);if !ok{userFeaturesJSON(w,401,map[string]any{"status":"error","message":"Login required"});return};rows,err:=userDB.Query(`SELECT id,whatsapp_user_id,phone_number,status,linked_at,last_seen_at,current_send_total,today_send_total FROM public.user_whatsapp_accounts WHERE user_id=$1::uuid AND status<>'removed' ORDER BY linked_at`,id);if err!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var aid,waid,phone,status string;var linked time.Time;var seen *time.Time;var total,today int64;if rows.Scan(&aid,&waid,&phone,&status,&linked,&seen,&total,&today)==nil{connected:=false;if s:=getSession(waid);s!=nil&&s.client!=nil{connected=s.client.IsConnected()};out=append(out,map[string]any{"id":aid,"phone":phone,"status":status,"connected":connected,"linked_at":linked,"last_seen_at":seen,"current_send_total":total,"today_send_total":today})}};userFeaturesJSON(w,200,map[string]any{"status":"success","max":3,"accounts":out})}
func userWhatsAppRemoveHandler(w http.ResponseWriter,r *http.Request){id,ok:=userDBID(r);if !ok{userFeaturesJSON(w,401,map[string]any{"status":"error","message":"Login required"});return};var in struct{AccountID string `json:"account_id"`};if json.NewDecoder(r.Body).Decode(&in)!=nil||strings.TrimSpace(in.AccountID)==""{userFeaturesJSON(w,400,map[string]any{"status":"error","message":"account_id is required"});return};var waid string;if err:=userDB.QueryRow(`SELECT whatsapp_user_id FROM public.user_whatsapp_accounts WHERE id=$1::uuid AND user_id=$2::uuid AND status<>'removed'`,in.AccountID,id).Scan(&waid);err!=nil{userFeaturesJSON(w,404,map[string]any{"status":"error","message":"WhatsApp account not found"});return};if s:=getSession(waid);s!=nil&&s.client!=nil{s.mu.Lock();if s.client.IsLoggedIn(){_=s.client.Logout(context.Background())};s.mu.Unlock();removeSession(waid)};_,_=userDB.Exec(`UPDATE public.user_whatsapp_accounts SET status='removed',removed_at=now(),updated_at=now() WHERE id=$1::uuid AND user_id=$2::uuid`,in.AccountID,id);userFeaturesJSON(w,200,map[string]any{"status":"success","message":"WhatsApp account removed"})}
func userTaskClaimHandler(w http.ResponseWriter,r *http.Request){id,ok:=userDBID(r);if !ok{userFeaturesJSON(w,401,map[string]any{"status":"error","message":"Login required"});return};var in struct{TaskID string `json:"task_id"`;AccountID string `json:"whatsapp_account_id"`};if json.NewDecoder(r.Body).Decode(&in)!=nil||in.TaskID==""||in.AccountID==""{userFeaturesJSON(w,400,map[string]any{"status":"error","message":"task_id and whatsapp_account_id are required"});return};tx,err:=userDB.Begin();if err!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};defer tx.Rollback();var title,msg,target string;var reward float64;if err=tx.QueryRow(`SELECT title,message,target_phone,reward FROM public.task_definitions WHERE id=$1::uuid AND active=true`,in.TaskID).Scan(&title,&msg,&target,&reward);err!=nil||strings.TrimSpace(target)==""{userFeaturesJSON(w,404,map[string]any{"status":"error","message":"Task unavailable or has no target"});return};var waid string;if err=tx.QueryRow(`SELECT whatsapp_user_id FROM public.user_whatsapp_accounts WHERE id=$1::uuid AND user_id=$2::uuid AND status='active'`,in.AccountID,id).Scan(&waid);err!=nil{userFeaturesJSON(w,404,map[string]any{"status":"error","message":"WhatsApp account unavailable"});return};s:=getSession(waid);if s==nil||s.client==nil||!s.client.IsLoggedIn()||!s.client.IsConnected(){userFeaturesJSON(w,409,map[string]any{"status":"error","message":"Selected WhatsApp is not connected"});return};var claimID string;if err=tx.QueryRow(`INSERT INTO public.task_claims(task_id,user_id,whatsapp_account_id,target_phone,message,status,reward) SELECT $1::uuid,$2::uuid,$3::uuid,target_phone,message,'sending',reward FROM public.task_definitions WHERE id=$1::uuid RETURNING id`,in.TaskID,id,in.AccountID).Scan(&claimID);err!=nil{userFeaturesJSON(w,409,map[string]any{"status":"error","message":"Task already claimed or unavailable"});return};if err=tx.Commit();err!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};s.mu.Lock();sendErr:=safeSendMessage(waid,s.client,types.JID{User:target,Server:types.DefaultUserServer},msg);s.mu.Unlock();if sendErr!=nil{_,_=userDB.Exec(`UPDATE public.task_claims SET status='failed' WHERE id=$1::uuid`,claimID);userFeaturesJSON(w,502,map[string]any{"status":"error","message":sendErr.Error()});return};tx2,e:=userDB.Begin();if e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error","message":"Send succeeded but reward processing failed"});return};defer tx2.Rollback();var credited bool;if e=tx2.QueryRow(`SELECT EXISTS(SELECT 1 FROM public.earning_ledger WHERE task_claim_id=$1::uuid)`,claimID).Scan(&credited);e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};if credited{userFeaturesJSON(w,200,map[string]any{"status":"success","message":"Task already credited"});return};if _,e=tx2.Exec(`UPDATE public.task_claims SET status='sent',sent_at=now() WHERE id=$1::uuid`,claimID);e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};if _,e=tx2.Exec(`INSERT INTO public.earning_ledger(user_id,task_claim_id,amount,type,description) VALUES($1::uuid,$2::uuid,$3,'task_reward','WhatsApp task reward')`,id,claimID,reward);e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};if _,e=tx2.Exec(`UPDATE public.app_users SET balance=balance+$1,today_earning=today_earning+$1,total_earning=total_earning+$1,updated_at=now() WHERE id=$2::uuid`,reward,id);e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};if _,e=tx2.Exec(`UPDATE public.user_whatsapp_accounts SET current_send_total=current_send_total+1,today_send_total=today_send_total+1,last_seen_at=now(),updated_at=now() WHERE id=$1::uuid`,in.AccountID);e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return}
 parent:=id;for level:=1;level<=10;level++{var refID string;if e=tx2.QueryRow(`SELECT referred_by::text FROM public.app_users WHERE id=$1::uuid`,parent).Scan(&refID);e!=nil||refID==""{break};var pct float64;var active bool;if e=tx2.QueryRow(`SELECT commission_percent,active FROM public.mlm_settings WHERE level=$1`,level).Scan(&pct,&active);e!=nil||!active||pct<=0{parent=refID;continue};commission:=reward*pct/100;if commission>0{if _,e=tx2.Exec(`INSERT INTO public.referral_commissions(referrer_id,referred_user_id,task_claim_id,amount,level) VALUES($1::uuid,$2::uuid,$3::uuid,$4,$5)`,refID,parent,claimID,commission,level);e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};description:="Level "+strconv.Itoa(level)+" referral commission";if _,e=tx2.Exec(`INSERT INTO public.earning_ledger(user_id,task_claim_id,amount,type,description) VALUES($1::uuid,$2::uuid,$3,'referral_commission',$4)`,refID,claimID,commission,description);e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};if _,e=tx2.Exec(`UPDATE public.app_users SET balance=balance+$1,total_earning=total_earning+$1,updated_at=now() WHERE id=$2::uuid`,commission,refID);e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return}};parent=refID};if e=tx2.Commit();e!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};userFeaturesJSON(w,200,map[string]any{"status":"success","message":"Task completed","reward":reward,"claim_id":claimID})}
func userReferralsHandler(w http.ResponseWriter,r *http.Request){id,ok:=userDBID(r);if !ok{userFeaturesJSON(w,401,map[string]any{"status":"error"});return};rows,err:=userDB.Query(`SELECT u.user_id,u.display_name,u.created_at,coalesce(rc.total,0) FROM public.app_users u LEFT JOIN (SELECT referred_user_id,sum(amount) total FROM public.referral_commissions WHERE referrer_id=$1::uuid GROUP BY referred_user_id) rc ON rc.referred_user_id=u.id WHERE u.referred_by=$1::uuid ORDER BY u.created_at DESC`,id);if err!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var uid,name string;var created time.Time;var earned float64;if rows.Scan(&uid,&name,&created,&earned)==nil{out=append(out,map[string]any{"user_id":uid,"name":name,"joined_at":created,"commission":earned})}};var total float64;_=userDB.QueryRow(`SELECT coalesce(sum(amount),0) FROM public.referral_commissions WHERE referrer_id=$1::uuid`,id).Scan(&total);userFeaturesJSON(w,200,map[string]any{"status":"success","total_commission":total,"referrals":out})}
func userEarningsHandler(w http.ResponseWriter,r *http.Request){id,ok:=userDBID(r);if !ok{userFeaturesJSON(w,401,map[string]any{"status":"error"});return};rows,err:=userDB.Query(`SELECT amount,type,description,created_at FROM public.earning_ledger WHERE user_id=$1::uuid ORDER BY created_at DESC LIMIT 100`,id);if err!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var amount float64;var typ,desc string;var created time.Time;if rows.Scan(&amount,&typ,&desc,&created)==nil{out=append(out,map[string]any{"amount":amount,"type":typ,"description":desc,"created_at":created})}};userFeaturesJSON(w,200,map[string]any{"status":"success","earnings":out})}
func userSupportHandler(w http.ResponseWriter,r *http.Request){id,ok:=userDBID(r);if !ok{userFeaturesJSON(w,401,map[string]any{"status":"error"});return};if r.Method==http.MethodGet{rows,err:=userDB.Query(`SELECT id,subject,message,status,created_at,updated_at FROM public.customer_care_tickets WHERE user_id=$1::uuid ORDER BY created_at DESC`,id);if err!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var tid,sub,msg,status string;var created,updated time.Time;if rows.Scan(&tid,&sub,&msg,&status,&created,&updated)==nil{out=append(out,map[string]any{"id":tid,"subject":sub,"message":msg,"status":status,"created_at":created,"updated_at":updated})}};userFeaturesJSON(w,200,map[string]any{"status":"success","tickets":out});return};if r.Method!=http.MethodPost{userFeaturesJSON(w,405,map[string]any{"status":"error"});return};var in struct{Subject string `json:"subject"`;Message string `json:"message"`};if json.NewDecoder(r.Body).Decode(&in)!=nil||strings.TrimSpace(in.Subject)==""||strings.TrimSpace(in.Message)==""{userFeaturesJSON(w,400,map[string]any{"status":"error","message":"Subject and message are required"});return};_,err:=userDB.Exec(`INSERT INTO public.customer_care_tickets(user_id,subject,message) VALUES($1::uuid,$2,$3)`,id,strings.TrimSpace(in.Subject),strings.TrimSpace(in.Message));if err!=nil{userFeaturesJSON(w,500,map[string]any{"status":"error"});return};userFeaturesJSON(w,200,map[string]any{"status":"success","message":"Support ticket created"})}
func init(){http.HandleFunc("/api/user/tasks",userTasksHandler);http.HandleFunc("/api/user/tasks/claim",userTaskClaimHandler);http.HandleFunc("/api/user/whatsapp",userWhatsAppHandler);http.HandleFunc("/api/user/whatsapp/remove",userWhatsAppRemoveHandler);http.HandleFunc("/api/user/referrals",userReferralsHandler);http.HandleFunc("/api/user/earnings",userEarningsHandler);http.HandleFunc("/api/user/support",userSupportHandler)}
